<!-- subpkg-doctor/workspace/index.vue — 医生工作站，对齐 DoctorDashboard.vue
     调用 doctorAPI.getQueue, submitDiagnosis, reAnalyze。手机端 Tab 切换：队列 → 阅片 → AI摘要 → 诊断 → 沟通 -->
<template><view class="p"><NavBar title="医生工作站"/><view class="b"><view v-if="!current" class="q-section"><text class="q-title">待诊队列 ({{queue.length}}人)</text><LoadingSkeleton v-if="loadingQ"/><EmptyState v-else-if="queue.length===0" icon="✅" title="暂无待诊患者" desc="新会诊单到达后自动刷新"/><view v-else class="q-list"><view v-for="item in queue" :key="item.id" class="q-item" :class="{active:current?.id===item.id}" @tap="select(item)"><text class="qi-id">#{{item.id}}</text><text class="qi-name">{{item.patientName||item.patient?.username||'患者'}}</text><text class="qi-complaint">{{(item.patientComplaint||'').substring(0,30)||'待补充'}}</text><view class="qi-status" :class="'s-'+item.status">{{statusLabel(item.status)}}</view></view></view></view><template v-if="current"><view class="tabs"><view v-for="tab in tabs" :key="tab.key" class="tab" :class="{active:activeTab===tab.key}" @tap="activeTab=tab.key">{{tab.label}}</view></view><scroll-view scroll-y class="tab-content"><view v-if="activeTab==='image'" class="tc"><view class="img-frame" v-if="imgUrl"><image :src="imgUrl" mode="aspectFit" class="diag-img"/></view><view v-else class="noimg">暂无影像</view></view><view v-if="activeTab==='ai'" class="tc"><text class="sec-t">AI 诊断摘要</text><view v-if="aiSummary" class="ai-card"><text class="ais">{{aiSummary}}</text><view v-for="(f,i) in aiFindings" :key="i" class="ai-item"><text class="ait">{{f.type||'发现'}}</text><text class="aic">{{f.confidence!=null?(f.confidence*100).toFixed(1)+'%':'--'}}</text></view></view><EmptyState v-else icon="🤖" title="暂无AI分析" desc="可从左侧队列选择患者后重新调用AI"/><button class="btn-s mt" @tap="doReAnalyze" :loading="loadingAi">重新调用 AI</button></view><view v-if="activeTab==='diagnosis'" class="tc"><text class="sec-t">诊断建议</text><textarea class="diag-input" v-model="diagnosisText" placeholder="请填写本次影像会诊结论、风险判断以及后续建议..."/><text class="char-count">{{diagnosisText.length}}字</text><button class="btn-p mt" @tap="doSubmit" :loading="submitting" :disabled="!diagnosisText.trim()">提交诊断报告</button></view><view v-if="activeTab==='chat'" class="tc"><text class="sec-t">医患沟通</text><LoadingSkeleton v-if="chatLoading"/><view v-else-if="messages.length===0" style="color:rgba(200,218,242,0.5);padding:40rpx 0;text-align:center">暂无沟通记录</view><view v-else class="chat-list"><view v-for="m in messages" :key="m.id" class="cb-msg" :class="m.senderRole==='DOCTOR'?'cm-d':'cm-p'"><text class="cbm-meta">{{m.senderRole==='DOCTOR'?'我':(current.patientName||'患者')}} · {{m.createdAt}}</text><text class="cbm-content">{{m.content}}</text></view></view><view class="chat-bar"><input class="cbi" v-model="chatInput" placeholder="输入沟通内容..."/><button class="cbs" @tap="doSendChat" :disabled="!chatInput.trim()">发送</button></view></view></scroll-view></template></view></view></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';import NavBar from '@/components/nav-bar.vue';import LoadingSkeleton from '@/components/loading-skeleton.vue';import EmptyState from '@/components/empty-state.vue';import {doctorAPI} from '@/api/doctor';import {ensureImageUrl} from '@/utils/image';import {useUserStore} from '@/stores/user';import apiClient from '@/api/http'
const userStore=useUserStore()
const queue=ref([]);const current=ref(null);const loadingQ=ref(true);const loadingAi=ref(false);const submitting=ref(false)
const diagnosisText=ref('');const messages=ref([]);const chatInput=ref('');const chatLoading=ref(false)
const activeTab=ref('image')
const tabs=[{key:'image',label:'阅片'},{key:'ai',label:'AI摘要'},{key:'diagnosis',label:'诊断'},{key:'chat',label:'沟通'}]
let qt=null
const imgUrl=computed(()=>current.value?ensureImageUrl(current.value.imageUrl):null)
const aiAnalysis=computed(()=>{try{if(current.value?.aiAnalysisJson)return typeof current.value.aiAnalysisJson==='string'?JSON.parse(current.value.aiAnalysisJson):current.value.aiAnalysisJson}catch{return null}return null})
const aiSummary=computed(()=>{const a=aiAnalysis.value;if(!a)return'';if(Array.isArray(a.findings)&&a.findings.length>0){const f=a.findings[0];return `AI已识别${a.findings.length}项征象，首要关注${f.type||'影像征象'}`}return a.diagnosis||a.result||a.summary||''})
const aiFindings=computed(()=>Array.isArray(aiAnalysis.value?.findings)?aiAnalysis.value.findings.slice(0,5):[])
const statusLabel=(s)=>{const m={WAITING:'待诊',PENDING:'待诊',IN_PROGRESS:'会诊中',COMPLETED:'已完成',FINISHED:'已完成'};return m[s]||s||'待诊'}
const loadQueue=async()=>{try{const r=await doctorAPI.getQueue();const l=Array.isArray(r)?r:(r?.data||[]);queue.value=l}catch(e){}finally{loadingQ.value=false}}
const select=async(item)=>{current.value=item;diagnosisText.value=item.doctorDiagnosis||'';activeTab.value='image';await loadMessages()}
const loadMessages=async()=>{if(!current.value)return;chatLoading.value=true;try{const r=await apiClient.get(`/health-consultation/query/chat?consultationId=${current.value.id}`);messages.value=Array.isArray(r)?r:(r?.data||[])}catch{}finally{chatLoading.value=false}}
const doReAnalyze=async()=>{if(!current.value)return;loadingAi.value=true;try{const r=await doctorAPI.reAnalyze(current.value.id);current.value=r?.data||r}catch(e){uni.showToast({title:'AI分析失败',icon:'none'})}finally{loadingAi.value=false}}
const doSubmit=async()=>{if(!current.value||!diagnosisText.value.trim())return;submitting.value=true;try{await doctorAPI.submitDiagnosis(current.value.id,userStore.userId||1,diagnosisText.value.trim());uni.showToast({title:'诊断已提交',icon:'success'});queue.value=queue.value.filter(i=>i.id!==current.value.id);current.value=null}catch(e){uni.showToast({title:'提交失败',icon:'none'})}finally{submitting.value=false}}
const doSendChat=async()=>{if(!current.value||!chatInput.value.trim())return;const content=chatInput.value.trim();chatInput.value='';try{await apiClient.post('/doctor/assistant/chat',null,{params:{message:content}});messages.value.push({id:Date.now(),senderRole:'DOCTOR',content,createdAt:new Date().toISOString()})}catch(e){uni.showToast({title:'发送失败',icon:'none'})}}
onMounted(()=>{loadQueue();qt=setInterval(loadQueue,5000)})
onBeforeUnmount(()=>{if(qt)clearInterval(qt)})
</script>
<style scoped>.p{min-height:100vh;background:#040b16}.b{padding:20rpx 28rpx}.q-title{font-size:30rpx;font-weight:700;color:#f7fbff;margin-bottom:20rpx;display:block}.q-item{padding:20rpx;border-radius:18rpx;background:rgba(8,20,35,0.8);border:1px solid rgba(125,211,252,0.08);margin-bottom:14rpx;display:flex;align-items:center;gap:16rpx}.q-item.active{border-color:rgba(94,234,212,0.3);background:linear-gradient(135deg,rgba(34,197,94,0.1),rgba(14,165,233,0.18))}.qi-id{font-size:24rpx;color:#70d6ff;font-weight:700}.qi-name{font-size:28rpx;color:#f0f6ff;flex:1}.qi-complaint{font-size:22rpx;color:rgba(200,218,242,0.5)}.qi-status{padding:4rpx 16rpx;border-radius:999rpx;font-size:20rpx;font-weight:600}.s-PENDING,.s-WAITING{background:rgba(56,189,248,0.12);color:#8be5ff}.s-COMPLETED,.s-FINISHED{background:rgba(74,222,128,0.14);color:#9ff1b5}.tabs{display:flex;gap:8rpx;margin:20rpx 0;background:rgba(255,255,255,0.04);border-radius:999rpx;padding:6rpx}.tab{flex:1;height:64rpx;display:flex;align-items:center;justify-content:center;border-radius:999rpx;font-size:24rpx;color:rgba(200,218,242,0.65)}.tab.active{background:rgba(56,189,248,0.18);color:#f0f6ff;font-weight:700}.tab-content{min-height:500rpx;padding:20rpx 0;padding-bottom:140rpx}.tc{display:flex;flex-direction:column;gap:20rpx}.sec-t{font-size:28rpx;font-weight:700;color:#f0f6ff;display:block}.img-frame{width:100%;min-height:500rpx;border-radius:20rpx;background:rgba(6,17,30,0.95);border:1px solid rgba(125,211,252,0.12);display:flex;align-items:center;justify-content:center;overflow:hidden}.diag-img{width:100%;height:100%}.noimg{min-height:300rpx;display:flex;align-items:center;justify-content:center;color:rgba(200,218,242,0.4);font-size:28rpx}.ai-card{padding:24rpx;border-radius:20rpx;background:rgba(8,20,35,0.72);border:1px solid rgba(125,211,252,0.08)}.ais{font-size:28rpx;color:rgba(210,225,245,0.8);line-height:1.7;display:block;margin-bottom:20rpx}.ai-item{display:flex;justify-content:space-between;padding:16rpx;border-radius:14rpx;background:rgba(8,20,35,0.5);border:1px solid rgba(125,211,252,0.06);margin-bottom:10rpx}.ait{font-size:26rpx;color:#f0f6ff;font-weight:600}.aic{font-size:24rpx;color:#70d6ff}.btn-s,.btn-p{width:100%;height:80rpx;border-radius:999rpx;font-size:28rpx;font-weight:700;border:none}.btn-s{background:rgba(8,20,35,0.82);border:1px solid rgba(125,211,252,0.16);color:#ecf8ff}.btn-p{background:linear-gradient(135deg,#5eead4,#38bdf8);color:#032032}.mt{margin-top:20rpx}.diag-input{width:100%;min-height:300rpx;padding:24rpx;border-radius:20rpx;background:rgba(6,16,29,0.9);border:1px solid rgba(125,211,252,0.1);color:#eef7ff;font-size:28rpx;line-height:1.8}.char-count{font-size:22rpx;color:rgba(200,218,242,0.4);text-align:right}.chat-list{display:flex;flex-direction:column;gap:16rpx}.cb-msg{max-width:80%;padding:16rpx 20rpx;border-radius:16rpx}.cm-d{margin-left:auto;background:linear-gradient(135deg,rgba(14,165,233,0.26),rgba(16,185,129,0.22));border:1px solid rgba(94,234,212,0.18)}.cm-p{background:rgba(8,20,35,0.7);border:1px solid rgba(125,211,252,0.08)}.cbm-meta{font-size:20rpx;color:rgba(200,218,242,0.5);display:block;margin-bottom:6rpx}.cbm-content{font-size:26rpx;color:#eef7ff;line-height:1.7}.chat-bar{position:fixed;bottom:0;left:0;right:0;padding:16rpx 28rpx;background:rgba(4,11,22,0.98);border-top:1px solid rgba(125,211,252,0.08);display:flex;gap:16rpx;align-items:center;padding-bottom:env(safe-area-inset-bottom)}.cbi{flex:1;height:76rpx;padding:0 24rpx;border-radius:999rpx;background:rgba(255,255,255,0.06);color:#f0f6ff;font-size:26rpx;border:1px solid rgba(125,211,252,0.12)}.cbs{height:76rpx;padding:0 32rpx;border-radius:999rpx;background:linear-gradient(135deg,#5eead4,#38bdf8);color:#032032;font-size:26rpx;font-weight:700;border:none}</style>
